heed = { version = "0.22.1", default-features = false }
ordered-float = "5.0.0"
roaring = "0.11.1"
thiserror = "2.0.12"
steppe = { version = "0.4.0", default-features = false }
zerometry = { version = "0.3.0" }

[dependencies]
geo = { workspace = true }
geo-types = { workspace = true }
geojson = { workspace = true }
h3o = { workspace = true }
heed = { workspace = true }
